<script setup lang="ts">
import { onUnmounted,ref } from 'vue'
import type { API } from './api'
import { isCancelled } from './console'
const props=defineProps<{api:API}>(),emit=defineEmits<{submitted:[]}>()
const dialog=ref<HTMLDialogElement|null>(null),source=ref<any>(null),content=ref(''),kind=ref('fact'),importance=ref(3),checked=ref(false),busy=ref(false),error=ref('')
let alive=true,version=0
async function open(messageID:string){const at=++version;source.value=null;content.value='';checked.value=false;error.value='';kind.value='fact';importance.value=3;dialog.value?.showModal();busy.value=true;try{const result=await props.api.request('/claim-source/'+encodeURIComponent(messageID),undefined,'GET','manual-review-source');if(alive&&at===version)source.value=result}catch(e){if(alive&&at===version&&!isCancelled(e))error.value=(e as Error).message}finally{if(at===version)busy.value=false}}
function close(){if(!busy.value){version++;dialog.value?.close();source.value=null;content.value='';checked.value=false}}
async function submit(){if(busy.value||!source.value?.personal_claim_eligible||!checked.value||!content.value.trim())return;busy.value=true;try{await props.api.request('/memory-reviews/propose',{message_id:source.value.message_id,content:content.value.trim(),kind:kind.value,importance:importance.value});if(alive){dialog.value?.close();emit('submitted')}}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{busy.value=false}}
defineExpose({open});onUnmounted(()=>{alive=false;version++;source.value=null;content.value=''})
</script>
<template><Teleport to="body"><dialog ref="dialog" class="candidate-dialog" aria-labelledby="candidate-title" @cancel="(e:Event)=>{if(busy)e.preventDefault();else close()}"><header><h2 id="candidate-title">从本人原话提出记忆候选</h2><button type="button" :disabled="busy" aria-label="关闭记忆候选" @click="close">×</button></header><p>只提出待审候选，不调用模型，不直接写入有效长期记忆。请保留原话的主体、条件与否定含义。</p><p v-if="error" role="alert" class="candidate-error">{{ error }}</p><template v-if="source"><h3>来源原文</h3><blockquote>{{ source.content }}</blockquote><p v-if="!source.personal_claim_eligible" class="candidate-error">此来源不能作为本人记忆。公开语料只供实验与浏览，不能转换为你的个人事实。</p><form v-else @submit.prevent="submit"><label>原话支持的长期事实或偏好<textarea v-model="content" required maxlength="4000" rows="4" placeholder="请核对原话后填写，不要补入原话没有的信息。" :disabled="busy"/></label><div class="candidate-fields"><label>类型<select v-model="kind" :disabled="busy"><option value="fact">事实</option><option value="preference">偏好</option><option value="profile">画像</option><option value="goal">目标</option><option value="procedure">流程</option></select></label><label>重要度<select v-model.number="importance" :disabled="busy"><option v-for="n in 5" :key="n" :value="n">{{ n }} / 5</option></select></label></div><label class="candidate-check"><input v-model="checked" type="checkbox" required :disabled="busy"/>我已核对原话，确认候选没有改变其含义。</label><footer><button type="button" :disabled="busy" @click="close">取消</button><button type="submit" class="primary" :disabled="busy||!checked||!content.trim()">{{ busy?'正在提交…':'提交并前往候选审核' }}</button></footer></form></template><p v-else-if="busy">正在核对来源…</p></dialog></Teleport></template>
<style scoped>
.candidate-dialog{width:min(660px,calc(100% - 32px));max-height:88dvh;overflow:auto;padding:25px;border:1px solid #dce6d7;border-radius:15px;background:white;color:#35503f;box-shadow:0 20px 80px #12382730;font:13px/1.8 "Segoe UI","Microsoft YaHei",sans-serif}.candidate-dialog::backdrop{background:#16312370;backdrop-filter:blur(3px)}header{display:flex;justify-content:space-between;gap:15px;align-items:center}h2{margin:0;font-size:18px}header button{border:0;background:none;font-size:24px;color:#82957d}h3{font-size:12px;margin:18px 0 6px}p{font-size:12px;color:#7a8a73}blockquote{margin:0 0 18px;background:#f3f7ee;padding:15px;border-left:3px solid #b5c9a9;max-height:190px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}label{display:grid;gap:6px;font-size:12px;margin-bottom:15px}textarea,select{font:inherit;color:inherit;background:#fbfdf9;border:1px solid #dce6d7;border-radius:8px;padding:10px;width:100%;box-sizing:border-box}.candidate-fields{display:grid;grid-template-columns:1fr 1fr;gap:15px}.candidate-check{display:flex;align-items:flex-start;gap:9px}.candidate-check input{margin-top:5px}footer{display:flex;justify-content:flex-end;gap:10px}footer button{border:1px solid #dce6d7;border-radius:8px;padding:9px 14px;background:#fff;color:#46654b;font:inherit;cursor:pointer}.primary{background:#326749!important;border-color:#326749!important;color:white!important}.candidate-error{background:#fff0e6;padding:10px;border-radius:7px;color:#965f3d!important}button:disabled{opacity:.5;cursor:wait}
</style>
